Using vertices 0 through n−1 and edges as [from, to, weight] triples, this implements Dijkstra’s algorithm with a binary min-heap. Stale entries are skipped; unreachable vertices become null. The attachment does not explicitly specify those input representation conventions.

```javascript
function solve(n, edges, source) {
  const adj = Array.from({ length: n }, () => []);
  for (const [from, to, weight] of edges) {
    adj[from].push([to, weight]);
  }

  const heap = [];

  function push(item) {
    let i = heap.length;
    heap.push(item);
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= item[0]) break;
      heap[i] = heap[parent];
      i = parent;
    }
    heap[i] = item;
  }

  function pop() {
    const minimum = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      let i = 0;
      while (2 * i + 1 < heap.length) {
        let child = 2 * i + 1;
        if (child + 1 < heap.length &&
            heap[child + 1][0] < heap[child][0]) {
          child++;
        }
        if (last[0] <= heap[child][0]) break;
        heap[i] = heap[child];
        i = child;
      }
      heap[i] = last;
    }
    return minimum;
  }

  const dist = Array(n).fill(Infinity);
  dist[source] = 0;
  push([0, source]);

  while (heap.length > 0) {
    const [distance, vertex] = pop();
    if (distance !== dist[vertex]) continue;

    for (const [next, weight] of adj[vertex]) {
      const candidate = distance + weight;
      if (candidate < dist[next]) {
        dist[next] = candidate;
        push([candidate, next]);
      }
    }
  }

  return dist.map(distance => distance === Infinity ? null : distance);
}
```

Call solve(n, edges, source) with a valid source and nonnegative, finite weights; path sums must fit JavaScript’s numeric precision. Zero-weight edges, self-loops, parallel edges, and disconnected vertices are supported.

For V = n and E = edges.length, time is O(V + E log(E + 2)) and space is O(V + E).

