Use breadth-first search over all eight directions, marking cells visited when enqueued. Distances start at 1 because path length counts cells; the input grid is not modified.

```javascript
function solve(grid) {
  const n = grid.length;
  if (n === 0 || grid[0][0] !== 0 || grid[n - 1][n - 1] !== 0) {
    return -1;
  }

  const visited = Array.from({ length: n }, () => Array(n).fill(false));
  const queue = [[0, 0, 1]];
  visited[0][0] = true;
  let head = 0;

  while (head < queue.length) {
    const [row, col, distance] = queue[head++];
    if (row === n - 1 && col === n - 1) return distance;

    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const nr = row + dr;
        const nc = col + dc;
        if (nr >= 0 && nr < n && nc >= 0 && nc < n &&
            grid[nr][nc] === 0 && !visited[nr][nc]) {
          visited[nr][nc] = true;
          queue.push([nr, nc, distance + 1]);
        }
      }
    }
  }

  return -1;
}
```

Call solve(grid) directly. Time: O(n²). Auxiliary space: O(n²), for an n × n grid.

